import { LearningRule } from '../types';

/**
 * Generates formatted markdown for .git/learnings/ entry
 */
export function generateLearningMarkdown(rule: LearningRule): string {
  return `# ${rule.title}

**Date:** ${rule.date}  
**Source Ref:** ${rule.slug}  

---

## ⚡ What Happened
${rule.whatHappened}

## 📋 The Durable Rule
> **Rule:** ${rule.rule}

---
*Generated by Tributary Epistemic Memory Engine*
`;
}

/**
 * Creates a normalized filename for a learning entry: YYYY-MM-DD-<slug>.md
 */
export function generateLearningFilename(date: string, slug: string): string {
  const cleanSlug = slug
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  return `.git/learnings/${date}-${cleanSlug}.md`;
}
